type Guide = { goals: string[]; checks: string[] };

export const remainingChapterGuides: Record<"14" | "15" | "16" | "17" | "18" | "19", Record<"en" | "fr", Guide>> = {
  "14": {
    en: { goals: ["Distinguish native terminal PHP from the structure PHPAML adds, then create and run a Console project.", "Read input safely, choose the correct output channel, validate values, and return meaningful exit statuses.", "Move domain behavior into typed classes and make it testable without waiting for interactive input.", "Handle known failures, paths, writes, and sensitive values without hiding errors or exposing secrets.", "Combine prompting, validation, hashing, verification, objects, and tests into one small maintainable tool."], checks: ["Can you explain what aml run contributes without claiming PHP needed PHPAML to work in a terminal?", "What happens when fgets returns false, the age is not numeric, or the program is used by another script?", "Can the calculation class be tested with ordinary arguments and no terminal attached?", "Does every caught exception produce an understandable diagnostic and a non-zero status without revealing sensitive data?", "Can the program prove a password matches without ever recovering or printing the original value?"] },
    fr: { goals: ["Distinguer le PHP terminal natif de la structure ajoutée par PHPAML, puis créer et exécuter un projet Console.", "Lire une entrée en sécurité, choisir le bon canal de sortie, valider et retourner un statut significatif.", "Déplacer le comportement métier dans des classes typées testables sans saisie interactive.", "Gérer erreurs connues, chemins, écritures et valeurs sensibles sans masquer les pannes ni exposer de secrets.", "Réunir questions, validation, hachage, vérification, objets et tests dans un petit outil maintenable."], checks: ["Pouvez-vous expliquer l’apport de aml run sans prétendre que PHPAML a inventé l’exécution terminal de PHP ?", "Que se passe-t-il si fgets retourne false, si l’âge n’est pas numérique ou si un script appelle le programme ?", "La classe de calcul se teste-t-elle avec de simples arguments, sans terminal connecté ?", "Chaque exception capturée produit-elle un diagnostic clair et un statut non nul sans révéler de donnée sensible ?", "Le programme prouve-t-il la correspondance d’un mot de passe sans retrouver ni afficher sa valeur originale ?"] },
  },
  "15": {
    en: { goals: ["Understand the boundary between AML, the framework, project source, and reconstructible runtime.", "Select the correct project and generator commands while predicting every file they are allowed to create.", "Rebuild dependencies and diagnose environment failures without modifying application source as a workaround.", "Operate serve, run, test, update, and cache commands with clear expectations about side effects.", "Complete a creation-to-recovery exercise and preserve evidence that another developer can reproduce."], checks: ["If AML is updated, which project files may change automatically and which must remain untouched?", "Why does make:model remain independent from Data while make:entity requires the module?", "Can runtime be removed and rebuilt while every source checksum stays identical?", "Which commands only observe, which write locally, and which may contact or modify an external system?", "Could a teammate repeat the procedure using only the recorded commands, versions, results, and checksums?"] },
    fr: { goals: ["Comprendre la frontière entre AML, framework, source du projet et runtime reconstructible.", "Choisir le bon projet et le bon générateur en prédisant exactement les fichiers qu’ils peuvent créer.", "Reconstruire les dépendances et diagnostiquer l’environnement sans modifier la source comme contournement.", "Exploiter serve, run, test, update et cache avec des attentes claires sur leurs effets.", "Réaliser un exercice création-récupération et conserver des preuves reproductibles par une autre personne."], checks: ["Quand AML est mis à jour, quels fichiers du projet peuvent changer automatiquement et lesquels doivent rester intacts ?", "Pourquoi make:model reste-t-il indépendant de Data tandis que make:entity exige ce module ?", "runtime peut-il être retiré puis reconstruit sans changer aucune empreinte de la source ?", "Quelles commandes observent seulement, écrivent localement ou peuvent joindre et modifier un système externe ?", "Un collègue peut-il répéter la procédure avec les seules commandes, versions, sorties et empreintes consignées ?"] },
  },
  "16": {
    en: { goals: ["Translate concrete product and security risks into tests that produce useful evidence.", "Choose unit or integration scope deliberately and test supported databases with their real engines.", "Verify complete HTTP contracts and reserve browser automation for behavior only a browser can prove.", "Prepare production configuration, observability, backups, and recovery rather than checking only a happy path.", "Define an ordered release gate whose artifacts and decision can be audited later."], checks: ["For every serious risk, is there a named test level and a visible expected result?", "Would a fake adapter hide the very driver, locking, transaction, or filesystem behavior this test claims to prove?", "Do tests cover anonymous, forbidden, invalid, missing, failure, and successful responses—not only status 200?", "Has the team actually restored a backup and rolled back a release, or merely documented the commands?", "Can you identify exactly which failed check blocks publication and where its evidence is stored?"] },
    fr: { goals: ["Transformer les risques produit et sécurité concrets en tests fournissant des preuves utiles.", "Choisir volontairement un périmètre unitaire ou intégration et tester les bases annoncées sur leurs vrais moteurs.", "Vérifier les contrats HTTP complets et réserver le navigateur aux comportements qu’il est seul à prouver.", "Préparer configuration, observabilité, sauvegardes et récupération plutôt que le seul chemin heureux.", "Définir une porte de livraison ordonnée dont les artefacts et la décision restent auditables."], checks: ["Chaque risque grave possède-t-il un niveau de test nommé et un résultat attendu visible ?", "Un faux adaptateur masquerait-il précisément le pilote, verrou, transaction ou système de fichiers à prouver ?", "Les tests couvrent-ils anonyme, interdit, invalide, absent, panne et succès, pas seulement le statut 200 ?", "L’équipe a-t-elle réellement restauré une sauvegarde et annulé une release, ou seulement écrit les commandes ?", "Pouvez-vous identifier le contrôle exact qui bloque la publication et l’emplacement de sa preuve ?"] },
  },
  "17": {
    en: { goals: ["Separate discovery, crawling, rendering, indexing, and ranking so the correct SEO problem is diagnosed.", "Write truthful metadata, language signals, and structured data that support genuinely useful content.", "Generate sitemap and robots directives from real public URLs without mistaking them for authorization.", "Combine technical audits, analytics, and Search Console while respecting what each source can prove.", "Publish one bilingual page and verify its content, status, metadata, discovery files, and indexing baseline."], checks: ["When a page has no impressions, do you know whether it was undiscovered, blocked, excluded, or simply not competitive?", "Would title, description, canonical, hreflang, and JSON-LD still be accurate if read aloud to a visitor?", "Could a supposedly private URL still be opened directly despite its robots.txt rule? If yes, add real access control.", "Are you using analytics to claim indexing, or Search Console to claim behavior after page load? Neither inference is valid.", "Was the public deployed URL audited and fetched, or did verification stop at localhost and generated files?"] },
    fr: { goals: ["Séparer découverte, exploration, rendu, indexation et classement afin de diagnostiquer le bon problème SEO.", "Écrire métadonnées, signaux de langue et données structurées honnêtes qui soutiennent un contenu réellement utile.", "Générer sitemap et directives robots depuis les vraies URL publiques sans les confondre avec une autorisation.", "Combiner audit technique, Analytics et Search Console en respectant ce que chaque source peut prouver.", "Publier une page bilingue et vérifier contenu, statut, métadonnées, fichiers de découverte et état initial d’indexation."], checks: ["Sans impression, savez-vous distinguer page inconnue, bloquée, exclue ou simplement non compétitive ?", "Titre, description, canonical, hreflang et JSON-LD resteraient-ils exacts s’ils étaient lus à un visiteur ?", "Une URL dite privée reste-t-elle accessible directement malgré robots.txt ? Si oui, ajoutez un vrai contrôle d’accès.", "Utilisez-vous Analytics pour prétendre à l’indexation ou Search Console pour décrire le comportement après chargement ?", "L’URL publique a-t-elle été auditée et chargée, ou la vérification s’est-elle arrêtée à localhost ?"] },
  },
  "18": {
    en: { goals: ["Treat a release as one immutable checksum that moves through environments with external configuration.", "Build a minimal production archive and independently verify its manifest and integrity evidence.", "Choose and validate the deployment strategy appropriate to the host before writing remotely.", "Separate upload, preparation, health verification, activation, retention, and rollback responsibilities.", "Rehearse a staging deployment and failure recovery while recording enough evidence for production."], checks: ["Can staging and production prove they received the exact same archive bytes?", "Does the archive omit .env, keys, logs, tests, caches, local databases, and deployment history?", "Did deploy:check and dry-run explain destination, permissions, planned changes, and unexpected deletions before deployment?", "Could code rollback leave the database schema or an external side effect incompatible with the restored version?", "How long did detection and rollback actually take during rehearsal, and what evidence confirms service recovery?"] },
    fr: { goals: ["Traiter une release comme une empreinte immuable traversant les environnements avec configuration externe.", "Construire une archive minimale et vérifier indépendamment son manifeste et sa preuve d’intégrité.", "Choisir et valider la stratégie adaptée à l’hôte avant toute écriture distante.", "Séparer transfert, préparation, santé, activation, conservation et retour arrière.", "Répéter un déploiement staging et sa récupération en conservant assez de preuves pour la production."], checks: ["Staging et production peuvent-ils prouver qu’ils ont reçu exactement les mêmes octets ?", "L’archive exclut-elle .env, clés, logs, tests, caches, bases locales et historique de déploiement ?", "deploy:check et dry-run ont-ils expliqué cible, permissions, changements et suppressions inattendues avant l’envoi ?", "Le rollback du code peut-il laisser un schéma ou un effet externe incompatible avec la version restaurée ?", "Combien de temps la détection et le retour ont-ils réellement pris, et quelle preuve confirme le rétablissement ?"] },
  },
  "19": {
    en: { goals: ["Preserve the first failure evidence and reduce the set of possible causes before changing anything.", "Distinguish shell installation, cache, project manifest, runtime, permission, and network failures.", "Trace Web failures through connection, public entry, routing, middleware, application code, persistence, and response.", "Use View overlays, request IDs, Data diagnostics, and production comparisons to locate subsystem failures.", "Solve controlled incidents with a repeatable decision tree and convert discoveries into prevention."], checks: ["Did you record the original message, directory, versions, status, and first log evidence before clearing or reinstalling?", "Which exact layer is broken, and what single observation rules out the neighboring layers?", "Does the status mean no server answered, the route is absent, access is forbidden, or application execution failed?", "Does the development detail stay out of production responses while remaining recoverable through protected logs and request IDs?", "After the fix, what test, diagnostic rule, safer default, or documentation change prevents the same blind spot?"] },
    fr: { goals: ["Conserver la première preuve et réduire les causes possibles avant tout changement.", "Distinguer les pannes d’installation shell, cache, manifeste, runtime, permission et réseau.", "Tracer les pannes Web à travers connexion, entrée publique, routes, middleware, code, persistance et réponse.", "Employer overlay View, request IDs, diagnostics Data et comparaison production pour localiser le module en échec.", "Résoudre des incidents contrôlés par un arbre répétable puis transformer les découvertes en prévention."], checks: ["Avez-vous noté message original, dossier, versions, statut et première preuve de journal avant d’effacer ou réinstaller ?", "Quelle couche précise est cassée et quelle observation unique élimine les couches voisines ?", "Le statut signifie-t-il absence de serveur, route absente, accès interdit ou échec d’exécution applicative ?", "Les détails de développement restent-ils hors des réponses production tout en étant retrouvables par logs protégés et request ID ?", "Après correction, quel test, diagnostic, défaut sûr ou changement documentaire supprime le même angle mort ?"] },
  },
};

